{
  "commitMessage": "feat(clients): add nif field to client form and edit page",
  "files": [
    {
      "path": "src/app/(crm)/clientes/client-form.tsx",
      "content": ""use client";

import { useActionState } from "react";
import { Button, ButtonLink } from "@/components/button";
import { Field } from "@/components/field";
import { emptyFormState, type FormState } from "@/lib/forms";

type Action = (prev: FormState, formData: FormData) => Promise<FormState>;

export function ClientForm({
  action,
  initial,
  cancelHref,
}: {
  action: Action;
  initial?: Record<string, string>;
  cancelHref: string;
}) {
  const [state, formAction, pending] = useActionState(action, emptyFormState);
  const value = (name: string) => state.values[name] ?? initial?.[name] ?? "";

  return (
    <form
      action={formAction}
      className="max-w-xl space-y-4 rounded-lg border border-slate-200 bg-white p-4"
      data-testid="client-form"
    >
      <Field
        label="Nombre"
        name="name"
        defaultValue={value("name")}
        error={state.errors.name}
        required
      />
      <Field
        label="NIF / CIF"
        name="nif"
        defaultValue={value("nif")}
        error={state.errors.nif}
      />
      <Field
        label="Email"
        name="email"
        type="email"
        defaultValue={value("email")}
        error={state.errors.email}
        required
      />
      <Field
        label="Teléfono"
        name="phone"
        type="tel"
        defaultValue={value("phone")}
        error={state.errors.phone}
      />
      <Field
        label="Empresa"
        name="company"
        defaultValue={value("company")}
        error={state.errors.company}
      />
      <div className="flex gap-2">
        <Button type="submit" disabled={pending} data-testid="save-button">
          {pending ? "Guardando…" : "Guardar"}
        </Button>
        <ButtonLink href={cancelHref} variant="secondary">
          Cancelar
        </ButtonLink>
      </div>
    </form>
  );
}
"
    },
    {
      "path": "src/app/(crm)/clientes/[id]/editar/page.tsx",
      "content": "import { notFound } from "next/navigation";
import { Suspense } from "react";
import { ResetOnHide } from "@/components/reset-on-hide";
import { Loading, PageHeader } from "@/components/page-header";
import { parseId } from "@/lib/ids";
import { updateClient } from "../../actions";
import { ClientForm } from "../../client-form";
import { getClient } from "../../queries";

export default function EditClientPage({
  params,
}: PageProps<"/clientes/[id]/editar">) {
  return (
    <Suspense fallback={<Loading />}>
      <EditClient params={params} />
    </Suspense>
  );
}

async function EditClient({
  params,
}: {
  params: PageProps<"/clientes/[id]/editar">["params"];
}) {
  const id = parseId((await params).id);
  const client = id ? await getClient(id) : null;
  if (!client) notFound();

  return (
    <>
      <PageHeader title={`Editar ${client.name}`} />
      <ResetOnHide>
        <ClientForm
          action={updateClient.bind(null, client.id)}
          cancelHref={`/clientes/${client.id}`}
          initial={{
            name: client.name,
            nif: client.nif ?? "",
            email: client.email,
            phone: client.phone ?? "",
            company: client.company ?? "",
          }}
        />
      </ResetOnHide>
    </>
  );
}
"
